import { AuthenticationClient, UserInfoClient } from 'auth0';
const auth0 = new AuthenticationClient({ domain, clientId, clientSecret });
const userInfo = new UserInfoClient({ domain });
async function getUserProfile(callbackUrl, codeVerifier) {
  const resp = await auth0.oauth.authorizationCodeGrantWithPKCE(
    { code: new URL(callbackUrl).searchParams.get('code'), redirect_uri: redirectUri },
    { codeVerifier }
  );
  const accessToken = resp.data.access_token;
  const profile = await userInfo.getUserInfo(accessToken);
  return { sub: profile.data.sub, email: profile.data.email };
}

